package top.hxzmc.community;

import android.content.Intent;
import android.security.keystore.*;
import android.util.Base64;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.security.cert.X509Certificate;
import java.util.*;
import java.util.concurrent.*;
import javax.net.ssl.*;
import javax.security.auth.x500.X500Principal;
import org.json.*;

/** Android implementation of packages/engine/core/direct-wire.mjs and direct-lobby.mjs. */
public final class GameLobby {
    private final CommunityApp app;
    private final ScheduledExecutorService timers=Executors.newScheduledThreadPool(2);
    private final Set<Socket> sockets=ConcurrentHashMap.newKeySet();
    private final Semaphore capacity=new Semaphore(64);
    private volatile long generation;
    private volatile JSONObject room,guest;
    private volatile ServerSocket server;
    private volatile GameLobbySignal p2p;
    private volatile String mode="idle",phase="尚未连接",error="",authority="",certificateAlias="",transport="";
    private volatile boolean ready,listed;
    private volatile int connections;
    private ScheduledFuture<?> heartbeat,expiry;
    public GameLobby(CommunityApp app){this.app=app;}
    static void thread(String name,Runnable task){Thread t=new Thread(task,name);t.setDaemon(true);t.start();}
    static void quiet(AutoCloseable value){if(value!=null)try{value.close();}catch(Exception ignored){}}
    static String hex(byte[] bytes){StringBuilder value=new StringBuilder();for(byte b:bytes)value.append(String.format(Locale.ROOT,"%02x",b&255));return value.toString();}
    private static int port(int value)throws IOException {if(value<1||value>65535)throw new IOException("端口必须在 1–65535 之间");return value;}
    private static String b64(byte[] value){return Base64.encodeToString(value,Base64.URL_SAFE|Base64.NO_PADDING|Base64.NO_WRAP);}
    private Object api(String path,String method,JSONObject body)throws Exception {return app.api(CommunityApp.obj("path",path,"method",method,"body",body));}
    private void changed(){app.event("lobby",status());}
    private void check(long ticket)throws IOException {if(generation!=ticket)throw new IOException("操作已取消");}
    private String identity(){JSONObject profile=app.credentials.optJSONObject("selectedProfile");return app.base+"|"+app.user.optString("uid")+"|"+(profile==null?"":profile.optString("id"));}
    public synchronized JSONObject status(){JSONObject publicRoom=null;if(room!=null){publicRoom=CommunityApp.obj("id",room.optString("id"),"name",room.optString("name"),"port",room.optInt("port"),"gamePort",room.optInt("gamePort"),"instance",room.optString("instance"),"hosts",room.optJSONArray("hosts"),"game",room.opt("game"),"expires",room.optLong("expires"),"leaseExpires",room.optLong("leaseExpires"),"invite",invitation(room));}return CommunityApp.obj("mode",mode,"phase",phase,"error",error,"ready",ready,"connections",connections,"listed",listed,"transport",transport,"room",publicRoom==null?JSONObject.NULL:publicRoom,"guest",guest==null?JSONObject.NULL:guest);}
    public Object call(JSONObject input)throws Exception {String action=input.optString("action","state");if(action.isEmpty())throw new IOException("未知联机操作");return action("lobby"+Character.toUpperCase(action.charAt(0))+action.substring(1),input);}
    public Object action(String action,JSONObject input)throws Exception {switch(action){case "lobbyState":return status();case "lobbyStatus":return status();case "lobbyAdapters":return adapters();case "lobbyHost":return host(input);case "lobbyInspect":return inspect(input);case "lobbyJoin":return join(input);case "lobbyClose":close("已离开联机");return status();default:throw new IOException("未知联机操作");}}
    public JSONObject hostConfig(){JSONObject value=room;return value!=null&&mode.equals("host")?CommunityApp.obj("port",value.optInt("gamePort"),"id",value.optString("id"),"instance",value.optString("instance")):null;}
    public JSONObject guestConfig(){JSONObject value=guest;return value==null?null:CommunityApp.obj("address",value.optString("address"),"instance",value.optString("instance"),"game",value.opt("game"));}
    public void markReady(int value){JSONObject current=room;if(current!=null&&value==current.optInt("gamePort")){ready=true;phase="世界已开放 · 等待玩家加入";error="";changed();publishAsync(current);}}
    public void markWaiting(){JSONObject current=room;if(current!=null){ready=false;phase="等待房主进入单人世界";changed();publishAsync(current);}}
    public void markError(String value){markWaiting();error=value;changed();}
    public void setGame(JSONObject game)throws Exception {validateGame(game);JSONObject current=room;if(current!=null){current.put("game",game);publishAsync(current);}}
    public synchronized void close(String reason){generation++;JSONObject old=room;room=null;guest=null;ready=false;listed=false;mode="idle";phase=reason;transport="";connections=0;if(heartbeat!=null)heartbeat.cancel(false);heartbeat=null;if(expiry!=null)expiry.cancel(false);expiry=null;quiet(server);server=null;quiet(p2p);p2p=null;for(Socket socket:sockets)quiet(socket);sockets.clear();metadata.clear();String alias=certificateAlias;certificateAlias="";if(!alias.isEmpty())try{KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);store.deleteEntry(alias);}catch(Exception ignored){}app.stopService(new Intent(app,GameLobbyService.class));changed();if(old!=null&&old.optBoolean("public"))thread("lobby-unpublish",()->{try{api("/api/lobby/rooms","DELETE",CommunityApp.obj("id",old.optString("id")));}catch(Exception ignored){}});}
    public void close(){close("联机已关闭");}
    private void startService(){app.startForegroundService(new Intent(app,GameLobbyService.class).setAction("start"));}
    private JSONObject host(JSONObject input)throws Exception {
        final long ticket; synchronized(this){if(!mode.equals("idle"))throw new IOException("请先关闭当前房间或离开连接");ticket=++generation;mode="checking";phase="验证创建权限";error="";}changed();
        try{JSONObject lease=(JSONObject)api("/api/lobby/lease","POST",new JSONObject());check(ticket);if(!lease.optBoolean("allowed")||lease.optLong("expiresAt")<=System.currentTimeMillis())throw new IOException("尚未获得开房权限");
            String name=input.optString("name","一起玩 Minecraft").trim();if(name.isEmpty()||name.length()>80)throw new IOException("请填写 1–80 字的房间名称");String scope=input.optString("scope","internet");if(!Arrays.asList("lan","internet").contains(scope))throw new IOException("请选择互联网或局域网");String method=input.optString("method","auto");if(!Arrays.asList("auto","p2p","ipv4","ipv6").contains(method))throw new IOException("请选择有效的连接方式");
            JSONObject game=input.optJSONObject("game");validateGame(game);int gamePort;try(ServerSocket free=new ServerSocket(0,1,InetAddress.getByName("127.0.0.1"))){gamePort=free.getLocalPort();}
            SSLServerSocket listener;JSONObject current;synchronized(this){check(ticket);SSLContext context=certificate();listener=(SSLServerSocket)context.getServerSocketFactory().createServerSocket(0,32);listener.setEnabledProtocols(protocols(listener.getSupportedProtocols()));
            byte[] key=new byte[32];new SecureRandom().nextBytes(key);current=CommunityApp.obj("v",1,"id",UUID.randomUUID().toString(),"key",b64(key),"fingerprint",certificateFingerprint(),"name",name,"port",listener.getLocalPort(),"gamePort",gamePort,"hosts",new JSONArray(),"p2p",false,"expires",System.currentTimeMillis()+12*3600000L,"leaseExpires",lease.getLong("expiresAt"),"owner",lease.optString("uid"),"public",input.optBoolean("public",true),"scope",scope,"game",game==null?JSONObject.NULL:game,"instance",input.optString("instance"));
            room=current;server=listener;authority=identity();}startService();thread("lobby-host-accept",()->acceptHost(listener,current,ticket));
            JSONArray addresses=adapters(),hosts=current.getJSONArray("hosts");for(int i=0;i<addresses.length()&&hosts.length()<8;i++){JSONObject row=addresses.getJSONObject(i);String host=row.getString("address");int family=row.getInt("family");if(scope.equals("lan")||(!method.equals("p2p")&&publicAddress(host)&&(method.equals("auto")||method.equals("ipv4")&&family==4||method.equals("ipv6")&&family==6)))hosts.put(host);}
            if(scope.equals("internet")&&(method.equals("auto")||method.equals("p2p"))){GameLobbySignal signaling;synchronized(this){check(ticket);p2p=signaling=new GameLobbySignal(app);}try{signaling.host(current,listener.getLocalPort());current.put("p2p",true);}catch(Exception e){error="P2P 协商暂不可用："+CommunityApp.reason(e);}}
            check(ticket);if(hosts.length()==0&&!current.optBoolean("p2p"))throw new IOException("没有可用的直连通道，请检查公网 IPv6 或改用同一局域网；手机暂不自动映射路由器端口");
            synchronized(this){check(ticket);mode="host";transport=hosts.length()>0?"direct":"p2p";phase="房间已创建 · 进入单人世界后自动开放";heartbeat=timers.scheduleWithFixedDelay(()->maintain(current),20,20,TimeUnit.SECONDS);expiry=timers.scheduleWithFixedDelay(()->{if(room==current&&(current.optLong("leaseExpires")<=System.currentTimeMillis()||current.optLong("expires")<=System.currentTimeMillis()||!authority.equals(identity())))close("开房授权或邀请已到期");},1,1,TimeUnit.SECONDS);}changed();publishAsync(current);return status();
        }catch(Exception e){if(generation==ticket){close("创建未完成");error=CommunityApp.reason(e);changed();}throw e;}
    }
    private SSLContext certificate()throws Exception {
        certificateAlias="hxz-room-"+UUID.randomUUID();KeyPairGenerator generator=KeyPairGenerator.getInstance("RSA","AndroidKeyStore");long now=System.currentTimeMillis();generator.initialize(new KeyGenParameterSpec.Builder(certificateAlias,KeyProperties.PURPOSE_SIGN|KeyProperties.PURPOSE_VERIFY).setKeySize(2048).setDigests(KeyProperties.DIGEST_SHA256,KeyProperties.DIGEST_SHA384,KeyProperties.DIGEST_SHA512).setSignaturePaddings(KeyProperties.SIGNATURE_PADDING_RSA_PKCS1,KeyProperties.SIGNATURE_PADDING_RSA_PSS).setCertificateSubject(new X500Principal("CN=HXZ direct room")).setCertificateSerialNumber(java.math.BigInteger.valueOf(now)).setCertificateNotBefore(new Date(now-60000)).setCertificateNotAfter(new Date(now+24*3600000L)).build());generator.generateKeyPair();KeyStore source=KeyStore.getInstance("AndroidKeyStore");source.load(null);final String alias=certificateAlias;final PrivateKey privateKey=(PrivateKey)source.getKey(alias,null);java.security.cert.Certificate[] raw=source.getCertificateChain(alias);final X509Certificate[] chain=Arrays.copyOf(raw,raw.length,X509Certificate[].class);X509ExtendedKeyManager manager=new X509ExtendedKeyManager(){public String[] getClientAliases(String t,Principal[] p){return null;}public String chooseClientAlias(String[] t,Principal[] p,Socket s){return null;}public String[] getServerAliases(String t,Principal[] p){return t.equals("RSA")?new String[]{alias}:null;}public String chooseServerAlias(String t,Principal[] p,Socket s){return t.equals("RSA")?alias:null;}public String chooseEngineServerAlias(String t,Principal[] p,SSLEngine e){return t.equals("RSA")?alias:null;}public X509Certificate[] getCertificateChain(String a){return alias.equals(a)?chain:null;}public PrivateKey getPrivateKey(String a){return alias.equals(a)?privateKey:null;}};SSLContext ssl=SSLContext.getInstance("TLS");ssl.init(new KeyManager[]{manager},null,new SecureRandom());return ssl;
    }
    private String certificateFingerprint()throws Exception {KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);return hex(MessageDigest.getInstance("SHA-256").digest(store.getCertificate(certificateAlias).getEncoded()));}
    private static String[] protocols(String[] available){return Arrays.stream(available).filter(v->v.equals("TLSv1.2")||v.equals("TLSv1.3")).toArray(String[]::new);}
    private void maintain(JSONObject current){if(room!=current)return;try{if(current.optLong("leaseExpires")<=System.currentTimeMillis()||current.optLong("expires")<=System.currentTimeMillis()||!authority.equals(identity())){close("开房授权或邀请已到期，请重新创建");return;}JSONObject lease=(JSONObject)api("/api/lobby/lease","POST",new JSONObject());if(room!=current)return;if(!lease.optBoolean("allowed")||!lease.optString("uid").equals(current.optString("owner"))){close("开房权限已撤销或账号已变更");return;}current.put("leaseExpires",lease.getLong("expiresAt"));GameLobbySignal signal=p2p;if(current.optBoolean("p2p")&&signal!=null&&!signal.hosting()){try{signal.host(current,current.optInt("port"));error="";}catch(Exception reconnect){error="P2P 协商暂不可用，将自动重试";changed();}}publish(current);}catch(Exception e){if(room==current){error="暂时无法续验权限，将在授权到期时关闭";changed();}}}
    private void publishAsync(JSONObject current){thread("lobby-publish",()->{try{publish(current);}catch(Exception e){if(room==current){listed=false;error="房间暂未显示在大厅："+CommunityApp.reason(e);changed();}}});}
    private void publish(JSONObject current)throws Exception {if(room!=current||!current.optBoolean("public"))return;JSONObject game=current.optJSONObject("game");api("/api/lobby/rooms","POST",CommunityApp.obj("invite",invitation(current),"ready",ready,"connections",connections,"scope",current.optString("scope"),"version",game==null?"":game.optString("minecraft"),"loader",game==null?"":game.optString("loader")));if(room==current){listed=true;changed();}else{try{api("/api/lobby/rooms","DELETE",CommunityApp.obj("id",current.optString("id")));}catch(Exception ignored){}}}
    private void acceptHost(SSLServerSocket listener,JSONObject current,long ticket){try{while(generation==ticket){SSLSocket socket=(SSLSocket)listener.accept();synchronized(this){if(generation!=ticket){quiet(socket);break;}sockets.add(socket);}if(!capacity.tryAcquire()){quiet(socket);sockets.remove(socket);continue;}thread("lobby-host-client",()->{try{socket.setSoTimeout(7000);socket.setTcpNoDelay(true);socket.startHandshake();JSONObject hello=readLine(socket);if(room!=current||current.optLong("expires")<=System.currentTimeMillis()||current.optLong("leaseExpires")<=System.currentTimeMillis())throw new IOException("房间邀请已失效");if(!MessageDigest.isEqual(hello.optString("id").getBytes(StandardCharsets.UTF_8),current.optString("id").getBytes(StandardCharsets.UTF_8))||!MessageDigest.isEqual(hello.optString("key").getBytes(StandardCharsets.UTF_8),current.optString("key").getBytes(StandardCharsets.UTF_8)))throw new IOException("房间邀请已失效");String operation=hello.optString("operation");if(operation.equals("probe")){writeLine(socket,CommunityApp.obj("ok",true,"name",current.optString("name"),"ready",ready,"connections",connections));quiet(socket);return;}if(!operation.equals("join"))throw new IOException("未知房间操作");if(!ready)throw new IOException("房主尚未进入世界，请稍后重试");synchronized(this){if(connections>=32)throw new IOException("房间连接数已满");connections++;}Socket upstream=new Socket();sockets.add(upstream);try{upstream.connect(new InetSocketAddress("127.0.0.1",current.getInt("gamePort")),6000);if(room!=current)throw new IOException("房间已关闭");writeLine(socket,CommunityApp.obj("ok",true,"name",current.optString("name")));socket.setSoTimeout(0);changed();CountDownLatch done=new CountDownLatch(1);bridge(socket,upstream,done::countDown);done.await();}finally{quiet(upstream);sockets.remove(upstream);synchronized(this){if(room==current)connections=Math.max(0,connections-1);}changed();}}catch(Exception e){try{writeLine(socket,CommunityApp.obj("ok",false,"error",CommunityApp.reason(e)));}catch(Exception ignored){}}finally{quiet(socket);sockets.remove(socket);capacity.release();}});}}catch(Exception e){if(generation==ticket){error="房间监听异常："+CommunityApp.reason(e);changed();}}}
    public static JSONObject parseInvitation(String raw)throws Exception{return GameLobbyWire.parseInvitation(raw);}
    public static String invitation(JSONObject v){return GameLobbyWire.invitation(v);}
    private static void validateGame(JSONObject v)throws IOException{GameLobbyWire.validateGame(v);}
    static JSONObject readLine(Socket s)throws Exception{return GameLobbyWire.readLine(s);}
    static void writeLine(Socket s,JSONObject v)throws Exception{GameLobbyWire.writeLine(s,v);}
    private Socket dial(JSONObject target,String host,String operation,long ticket)throws Exception {Socket raw=null,wrapped=null;try{check(ticket);raw=host.equals("p2p")?signalClient(ticket).dial(target):new Socket();synchronized(this){check(ticket);sockets.add(raw);}if(!host.equals("p2p"))raw.connect(new InetSocketAddress(host,port(target.getInt("port"))),6000);raw.setSoTimeout(10000);SSLSocket secure=GameLobbyWire.secure(raw,target);wrapped=secure;synchronized(this){check(ticket);sockets.remove(raw);sockets.add(secure);}writeLine(secure,CommunityApp.obj("operation",operation,"id",target.getString("id"),"key",target.getString("key")));JSONObject info=readLine(secure);if(!info.optBoolean("ok"))throw new IOException(info.optString("error","房间不可用"));secure.setSoTimeout(0);metadata.put(secure,info);return secure;}catch(Exception e){quiet(raw);quiet(wrapped);sockets.remove(raw);if(wrapped!=null)sockets.remove(wrapped);throw e;}}
    private synchronized GameLobbySignal signalClient(long ticket)throws Exception{check(ticket);if(p2p==null)p2p=new GameLobbySignal(app);return p2p;}
    private JSONObject inspect(JSONObject input)throws Exception {long ticket=generation;JSONObject target=parseInvitation(input.optString("invite"));String method=input.optString("method","auto");if(!Arrays.asList("auto","p2p","ipv4","ipv6").contains(method))throw new IOException("请选择有效的加入方式");long start=System.currentTimeMillis();JSONArray hosts=target.getJSONArray("hosts");for(int i=0;i<hosts.length();i++){String h=hosts.getString(i);if(method.equals("p2p")||method.equals("ipv4")&&h.contains(":")||method.equals("ipv6")&&!h.contains(":"))continue;try{check(ticket);boolean available=probeReady(target,h,ticket);return CommunityApp.obj("name",target.optString("name"),"game",target.opt("game"),"host",h,"latency",System.currentTimeMillis()-start,"ready",available);}catch(Exception ignored){}}
        if(target.optBoolean("p2p")&&(method.equals("auto")||method.equals("p2p"))){check(ticket);boolean available=probeReady(target,"p2p",ticket);return CommunityApp.obj("name",target.optString("name"),"game",target.opt("game"),"host","p2p","latency",System.currentTimeMillis()-start,"ready",available);}throw new IOException("所选直连方式不可达；双方 NAT 限制穿透时，请使用同一局域网或公网 IPv6");}
    private final Map<Socket,JSONObject> metadata=new ConcurrentHashMap<>();
    private boolean probeReady(JSONObject target,String host,long ticket)throws Exception {Socket socket=dial(target,host,"probe",ticket);try{return metadata.remove(socket).optBoolean("ready");}finally{quiet(socket);sockets.remove(socket);}}
    private JSONObject join(JSONObject input)throws Exception {final long ticket;synchronized(this){if(!mode.equals("idle"))throw new IOException("请先关闭当前房间或离开连接");ticket=++generation;mode="checking";phase="检测房主网络与世界";error="";}changed();try{JSONObject tested=inspect(input);check(ticket);if(!tested.optBoolean("ready"))throw new IOException("房主尚未进入世界，请稍后重试");JSONObject target=parseInvitation(input.getString("invite"));String host=tested.getString("host");ServerSocket listener;synchronized(this){check(ticket);listener=new ServerSocket(0,16,InetAddress.getByName("127.0.0.1"));server=listener;guest=CommunityApp.obj("name",target.optString("name"),"address","127.0.0.1:"+listener.getLocalPort(),"host",host,"instance",input.optString("instance"),"game",target.opt("game"));mode="guest";ready=true;phase="连接就绪 · 可以启动游戏";transport=host.equals("p2p")?"p2p":"direct";}startService();thread("lobby-guest-accept",()->{try{while(generation==ticket){Socket local=listener.accept();synchronized(this){if(generation!=ticket){quiet(local);break;}sockets.add(local);}if(!capacity.tryAcquire()){quiet(local);sockets.remove(local);continue;}thread("lobby-guest-client",()->{Socket remote=null;try{if(target.optLong("expires")<=System.currentTimeMillis())throw new IOException("房间邀请已过期");remote=dial(target,host,"join",ticket);check(ticket);metadata.remove(remote);Socket linked=remote;CountDownLatch done=new CountDownLatch(1);bridge(local,linked,done::countDown);done.await();}catch(Exception e){if(generation==ticket){error=CommunityApp.reason(e);changed();}}finally{quiet(remote);quiet(local);sockets.remove(local);if(remote!=null){sockets.remove(remote);metadata.remove(remote);}capacity.release();}});}}catch(Exception e){if(generation==ticket){error=CommunityApp.reason(e);changed();}}});changed();return status();}catch(Exception e){if(generation==ticket){close("加入未完成");error=CommunityApp.reason(e);changed();}throw e;}}
    static void bridge(Socket a,Socket b,Runnable finished){java.util.concurrent.atomic.AtomicBoolean done=new java.util.concurrent.atomic.AtomicBoolean();Runnable finish=()->{if(done.compareAndSet(false,true)){quiet(a);quiet(b);finished.run();}};for(int direction=0;direction<2;direction++){Socket from=direction==0?a:b,to=direction==0?b:a;thread("lobby-stream",()->{try{byte[] bytes=new byte[16384];int n;while((n=from.getInputStream().read(bytes))!=-1)to.getOutputStream().write(bytes,0,n);}catch(Exception ignored){}finally{finish.run();}});}}
    public static JSONArray adapters()throws Exception {JSONArray result=new JSONArray();Enumeration<NetworkInterface> all=NetworkInterface.getNetworkInterfaces();while(all!=null&&all.hasMoreElements()){NetworkInterface adapter=all.nextElement();if(!adapter.isUp()||adapter.isLoopback())continue;Enumeration<InetAddress> addresses=adapter.getInetAddresses();while(addresses.hasMoreElements()){InetAddress a=addresses.nextElement();if(a.isLoopbackAddress()||a.isLinkLocalAddress()||a.isMulticastAddress()||a.isAnyLocalAddress())continue;String address=a.getHostAddress();if(address==null||address.contains("%"))continue;result.put(CommunityApp.obj("name",adapter.getDisplayName(),"address",address,"family",a instanceof Inet6Address?6:4));}}return result;}
    private static boolean publicAddress(String address)throws Exception {InetAddress a=InetAddress.getByName(address);if(a instanceof Inet6Address){byte[] b=a.getAddress();return (b[0]&0xe0)==0x20&&!address.toLowerCase(Locale.ROOT).startsWith("2001:db8:")&&!address.startsWith("2001:0:");}byte[] b=a.getAddress();int x=b[0]&255,y=b[1]&255;return !(a.isSiteLocalAddress()||a.isLoopbackAddress()||a.isLinkLocalAddress()||a.isMulticastAddress()||x==0||x>=224||x==100&&y>=64&&y<=127||x==192&&y==0||x==198&&(y==18||y==19||y==51)||x==203&&y==0);}
}
